Class Product
  Define price As Integer;

  Method Constructor(p As Integer)
    This.price <- p;
  EndMethod

  Method FinalPrice() As Integer
    Return This.price;
  EndMethod
EndClass

Class ExpiringProduct Inherits From Product
  Method Constructor(p As Integer)
    Super.constructor(p);
  EndMethod

  Method FinalPrice() As Integer
    Return This.price Div 2;
  EndMethod
EndClass

Class OfferProduct Inherits From Product
  Method Constructor(p As Integer)
    Super.constructor(p);
  EndMethod

  Method FinalPrice() As Integer
    Return This.price - This.price * 25 Div 100;
  EndMethod
EndClass

Algorithm Kiosk
  Define tipo, price As Integer;
  Read tipo;
  Read price;
  Define product As Product <- New Product(price);
  If tipo = 2 Then
    product <- New ExpiringProduct(price);
  EndIf
  If tipo = 3 Then
    product <- New OfferProduct(price);
  EndIf
  Write product.FinalPrice();
EndAlgorithm

