Class Offer
  Define percent As Integer;
  Method Constructor(p As Integer)
    This.percent <- p;
  EndMethod
  Method Apply(price As Integer) As Integer
    Return price - price * This.percent Div 100;
  EndMethod
EndClass

Class Expiry
  Define days As Integer;
  Method Constructor(d As Integer)
    This.days <- d;
  EndMethod
  Method Apply(price As Integer) As Integer
    If This.days <= 2 Then
      Return price Div 2;
    EndIf
    Return price;
  EndMethod
EndClass

Class Product
  Define name As String;
  Define price As Integer;
  Define offer As Offer;
  Define expiry As Expiry;
  Method Constructor(n As String, p As Integer)
    This.name <- n;
    This.price <- p;
    This.offer <- New Offer(0);
    This.expiry <- New Expiry(365);
  EndMethod
  Method SetOffer(newOffer As Offer)
    This.offer <- newOffer;
  EndMethod
  Method SetExpiry(date As Expiry)
    This.expiry <- date;
  EndMethod
  Method FinalPrice() As Integer
    Return This.expiry.Apply(This.offer.Apply(This.price));
  EndMethod
EndClass

Algorithm Kiosk
  Define tipo, price As Integer;
  Read tipo;
  Read price;
  Define product As Product <- New Product("Product", price);
  If tipo = 3 Or tipo = 4 Then
    product.SetOffer(New Offer(25));
  EndIf
  If tipo = 2 Or tipo = 4 Then
    product.SetExpiry(New Expiry(1));
  EndIf
  Write product.FinalPrice();
EndAlgorithm
